int count_vowels(char s[]) {
    int count = 0;
    int i = 0;
    while (s[i] != '\0') {
        char ch = s[i];
        if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u') {
            count++;
        }
        i++;
    }
    return count;
}

int count_vowels(char s[]) {
    int count = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] == 'a' || s[i] == 'e' || s[i] == 'i' || s[i] == 'o' || s[i] == 'u') {
            count++;
        }
    }
    return count;
}

int count_vowels(char s[]) {
    int count = 0;
    int i = 0;
    while (s[i]) {
        int vowel = s[i] == 'a' || s[i] == 'e' || s[i] == 'i' || s[i] == 'o' || s[i] == 'u';
        if (vowel) count = count + 1;
        i++;
    }
    return count;
}
